import heapq

def shortest_path(edges, start, end):
    """
    有向グラフでの最短距離とその経路を計算する関数

    Args:
        edges: (from_node, to_node, weight) のタプルリスト
        start: 開始ノード
        end: 終了ノード

    Returns:
        (distance, path): 最短距離と経路のリスト（None, None）または (0, [start])

    Raises:
        ValueError: 負の重みのエッジがある場合
    """

    # 1. エッジ weight が負でないかチェック
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative weight not allowed")

    # 2. start == end の場合の特殊処理
    if start == end:
        return (0, [start])

    # 3. グラフを構築（ノードごとの隣接リスト）
    graph = {}
    all_nodes = set()

    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = []
        if to_node not in graph:
            graph[to_node] = []

        graph[from_node].append((to_node, weight))
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # 4. Dijkstra アルゴリズム
    distances = {node: float('inf') for node in all_nodes}
    predecessors = {node: None for node in all_nodes}
    distances[start] = 0

    pq = [(0, start)]
    visited = set()

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue

        visited.add(current_node)

        if not graph.get(current_node):
            continue

        for neighbor, weight in graph[current_node]:
            new_dist = current_dist + weight

            if new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                predecessors[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # 5. 経路が存在しない場合の判断
    if end not in all_nodes or distances[end] == float('inf'):
        return (None, None)

    # 6. 経路の再構築
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessors[current]

    path.reverse()

    return (distances[end], path)
